# Contiguity hints + autotune; 128-bit vectorized loads
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 512, 'YBLOCK': 1}, num_warps=4),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 4}, num_warps=8),
        triton.Config({'XBLOCK': 128, 'YBLOCK': 8}, num_warps=4),
        # ... other configs
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    xrange = tl.arange(0, XBLOCK)
    xrange = tl.max_contiguous(tl.multiple_of(xrange, XBLOCK), XBLOCK)  # KEY: alignment+contiguity
    xindex = xoffset + xrange[None, :]
    tmp0 = tl.load(in_ptr + (x2 + stride*y3), mask)   # now 128-bit vectorized
    tl.store(out_ptr + (permuted_idx), tmp0, mask)

def kernel_function(*inputs):
    grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
    kernel[grid](arg0, arg1, ynumel, xnumel)  # autotune selects tile sizes

